code='''from collections import deque

def transform(grid):
    # Downward flow: continue through 7; on hitting a 2, spread sideways
    # until both routes around the obstacle can continue downward.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    q = deque((r, c) for r in range(h) for c in range(w) if g[r][c] == 6)
    while q:
        r, c = q.popleft()
        if r + 1 >= h:
            continue
        if g[r + 1][c] == 7:
            directions = ((1, 0),)
        elif g[r + 1][c] == 2:
            directions = ((0, 1), (0, -1))
        else:
            directions = ()
        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            if 0 <= cc < w and g[rr][cc] == 7:
                g[rr][cc] = 6
                q.append((rr, cc))
    return g
'''
